// src/lib/mcp/tools/list-properties.ts
var list_properties_default = defineTool({
  name: "list_properties",
  title: "Lister les biens immobiliers",
  description: "Retourne les biens immobiliers Gestimmo Digital \xE0 Kinshasa (villas, appartements, bureaux, terrains). Filtres optionnels par type (Vente/Location) et par commune.",
  inputSchema: {
    type: z.enum(["Vente", "Location"]).optional().describe("Filtrer par type: Vente ou Location."),
    location: z.string().optional().describe("Filtrer par commune de Kinshasa (ex: Gombe, Ngaliema).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ type, location }) => {
    const loc = location?.toLowerCase();
    const results = properties.filter(
      (p) => (!type || p.type === type) && (!loc || p.location.toLowerCase().includes(loc))
    );
    return {
      content: [{ type: "text", text: JSON.stringify(results, null, 2) }],
      structuredContent: { properties: results, count: results.length }
    };
  }
});

// src/lib/mcp/tools/get-property.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z2 } from "npm:zod@^3.25.76";
var get_property_default = defineTool2({
  name: "get_property",
  title: "D\xE9tails d'un bien",
  description: "Retourne les d\xE9tails complets d'un bien immobilier par son id.",
  inputSchema: {
    id: z2.string().min(1).describe("Identifiant du bien (ex: villa-gombe-piscine).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const found = properties.find((p) => p.id === id);
    if (!found) {
      return {
        content: [{ type: "text", text: `Aucun bien trouv\xE9 pour l'id "${id}".` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(found, null, 2) }],
      structuredContent: { property: found }
    };
  }
});

