// src/lib/mcp/tools/send-contact-message.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z3 } from "npm:zod@^3.25.76";
import { createClient } from "npm:@supabase/supabase-js@^2.105.4";
var send_contact_message_default = defineTool4({
  name: "send_contact_message",
  title: "Envoyer un message de contact",
  description: "Envoie un message via le formulaire de contact Gestimmo Digital. Les messages re\xE7us ne sont PAS lisibles via MCP.",
  inputSchema: {
    name: z3.string().trim().min(1).max(100).describe("Nom complet de la personne."),
    email: z3.string().trim().email().max(255).describe("Adresse email de contact."),
    phone: z3.string().trim().max(30).optional().describe("T\xE9l\xE9phone (optionnel)."),
    message: z3.string().trim().min(1).max(2e3).describe("Contenu du message.")
  },
  annotations: { readOnlyHint: false, openWorldHint: false },
  handler: async ({ name, email, phone, message }) => {
    const url = process.env.SUPABASE_URL;
    const key = process.env.SUPABASE_PUBLISHABLE_KEY;
    if (!url || !key) {
      return {
        content: [{ type: "text", text: "Backend non configur\xE9." }],
        isError: true
      };
    }
    const supabase = createClient(url, key, {
      auth: { persistSession: false, autoRefreshToken: false }
    });
    const { error } = await supabase.from("contact_messages").insert({
      name,
      email,
      phone: phone ?? null,
      message
    });
    if (error) {
      return {
        content: [{ type: "text", text: `Erreur: ${error.message}` }],
        isError: true
      };
    }
    return {
      content: [
        {
          type: "text",
          text: "Message envoy\xE9 avec succ\xE8s. L'\xE9quipe Gestimmo Digital vous r\xE9pondra rapidement."
        }
      ],
      structuredContent: { ok: true }
    };
  }
});

